"""Generates wgmma_ops.cuh: wgmma m64nNk{16,8} SS (both operands K-major in shared memory) accumulate, bf16 and tf32.
Run: python gen_wgmma.py > wgmma_ops.cuh   (dev tool; the header is committed)."""

NS = (64, 128, 192, 256)
print(
    "// Generated by gen_wgmma.py. wgmma m64nNk16 (bf16) / m64nNk8 (tf32) SS, both operands K-major shared-memory descriptors, D += A B."
)
print("#pragma once")
print("#include <cstdint>")
print("#include <cuda_bf16.h>")
print("#include <cuda_fp16.h>")
print("namespace tr90 {")
print(
    "template <typename T, int N> __device__ __forceinline__ void mma(float (&d)[N / 2], uint64_t a, uint64_t b);"
)
for T, shape, ty, tail in (
    ("__nv_bfloat16", "k16", "bf16.bf16", ", 1, 1, 1, 0, 0"),
    ("float", "k8", "tf32.tf32", ", 1, 1, 1"),
    ("__half", "k16", "f16.f16", ", 1, 1, 1, 0, 0"),
):
    for n in NS:
        r = n // 2
        regs = ",".join(f"%{i}" for i in range(r))
        outs = ", ".join(f'"+f"(d[{i}])' for i in range(r))
        print(
            f"template <> __device__ __forceinline__ void mma<{T}, {n}>(float (&d)[{r}], uint64_t a, uint64_t b) {{"
        )
        print(
            f'  asm volatile("wgmma.mma_async.sync.aligned.m64n{n}{shape}.f32.{ty} {{{regs}}}, %{r}, %{r + 1}{tail};\\n"'
        )
        print(f'               : {outs} : "l"(a), "l"(b));')
        print("}")
print("}  // namespace tr90")

# mmaT (B MN-major) variants: appended by hand in the same form (bf16 only); see wgmma_ops.cuh
